import React, { useMemo, useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { customerSchema } from '../utils/validation';
import { 
  fetchCustomers, 
  createCustomer, 
  updateCustomer, 
  deleteCustomer,
  fetchCustomerAdvanceSummary,
  fetchCustomerAdvanceHistory,
  createCustomerAdvance,
  createCustomerAdvanceRefund,
} from '../utils/api';
import Loading from './Loading';
import useDebouncedValue from '../utils/useDebouncedValue';
import './Customers.css';

const CUSTOMER_FORM_DEFAULTS = {
  name: '',
  phone: '',
  email: '',
  address: '',
  city: '',
  state: '',
  pincode: '',
  gstin: '',
  location: 'Bhondsi',
  notes: '',
  tokenAmount: '',
  tokenPaymentMode: 'CASH',
};

const Customers = () => {
  const [customers, setCustomers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');
  const debouncedSearchQuery = useDebouncedValue(searchQuery, 250);
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const [advanceModalCustomer, setAdvanceModalCustomer] = useState(null);
  const [advanceSummary, setAdvanceSummary] = useState(null);
  const [advanceHistory, setAdvanceHistory] = useState([]);
  const [advanceLoading, setAdvanceLoading] = useState(false);
  const [remainingAdvanceByCustomerId, setRemainingAdvanceByCustomerId] = useState({});
  const [advanceAmount, setAdvanceAmount] = useState('');
  const [refundAmount, setRefundAmount] = useState('');
  const [refundDesc, setRefundDesc] = useState('');
  const [advanceDesc, setAdvanceDesc] = useState('');
  const [advancePaymentMode, setAdvancePaymentMode] = useState(
    () => localStorage.getItem('lastAdvancePaymentMode') || 'CASH'
  );
  const [refundPaymentMode, setRefundPaymentMode] = useState(
    () => localStorage.getItem('lastAdvanceRefundPaymentMode') || 'CASH'
  );

  const ADVANCE_PAYMENT_MODES = [
    { value: 'CASH', label: 'Cash' },
    { value: 'UPI', label: 'UPI' },
    { value: 'BANK_TRANSFER', label: 'Bank transfer' },
    { value: 'CHEQUE', label: 'Cheque' },
  ];

  const unwrapEntity = (value) =>
    value && typeof value === 'object' && value.data && typeof value.data === 'object'
      ? value.data
      : value;

  const unwrapList = (value) =>
    Array.isArray(value)
      ? value
      : Array.isArray(value?.data)
        ? value.data
        : [];

  // React Hook Form
  const { 
    register, 
    handleSubmit, 
    reset, 
    setValue,
    formState: { errors } 
  } = useForm({
    resolver: yupResolver(customerSchema),
    defaultValues: CUSTOMER_FORM_DEFAULTS,
  });

  const [, setFormData] = useState({
    name: '',
    phone: '',
    email: '',
    address: '',
    city: '',
    state: '',
    pincode: '',
    gstin: '',
    location: 'Bhondsi',
    notes: ''
  });

  const toList = (value) =>
    Array.isArray(value)
      ? value
      : Array.isArray(value?.data)
        ? value.data
        : [];

  const toEntity = (value) =>
    value && typeof value === 'object' && value.data && typeof value.data === 'object'
      ? value.data
      : value;

  useEffect(() => {
    loadCustomers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const loadAdvanceData = async (customerId) => {
    setAdvanceLoading(true);
    try {
      const [sumRaw, histRaw] = await Promise.all([
        fetchCustomerAdvanceSummary(customerId),
        fetchCustomerAdvanceHistory(customerId),
      ]);
      const sum = unwrapEntity(sumRaw);
      const hist = unwrapList(histRaw);
      setAdvanceSummary(sum || { totalAdvance: 0, totalUsed: 0, remaining: 0, oldBillPendingAmount: 0 });
      setAdvanceHistory(hist);
      if (sum && customerId != null) {
        setRemainingAdvanceByCustomerId((prev) => ({
          ...prev,
          [customerId]: Number(sum.remaining) || 0,
        }));
      }
    } catch (e) {
      console.error('Advance load failed:', e);
      setAdvanceSummary(null);
      setAdvanceHistory([]);
    } finally {
      setAdvanceLoading(false);
    }
  };

  const openAdvanceModal = (customer) => {
    setAdvanceModalCustomer(customer);
    setAdvanceAmount('');
    setRefundAmount('');
    setAdvanceDesc('');
    setRefundDesc('');
    setAdvancePaymentMode(localStorage.getItem('lastAdvancePaymentMode') || 'CASH');
    setRefundPaymentMode(localStorage.getItem('lastAdvanceRefundPaymentMode') || 'CASH');
    loadAdvanceData(customer.id);
  };

  const closeAdvanceModal = () => {
    setAdvanceModalCustomer(null);
    setAdvanceSummary(null);
    setAdvanceHistory([]);
  };

  const handleAddAdvance = async (e) => {
    e.preventDefault();
    if (!advanceModalCustomer) return;
    const amt = parseFloat(String(advanceAmount).replace(/[^\d.]/g, ''));
    if (!amt || amt <= 0) {
      alert('Enter a positive amount');
      return;
    }
    try {
      setAdvanceLoading(true);
      await createCustomerAdvance({
        customerId: advanceModalCustomer.id,
        amount: amt,
        paymentMode: advancePaymentMode || 'CASH',
        description: advanceDesc || undefined,
      });
      localStorage.setItem('lastAdvancePaymentMode', advancePaymentMode || 'CASH');
      setAdvanceAmount('');
      setAdvanceDesc('');
      await loadAdvanceData(advanceModalCustomer.id);
    } catch (err) {
      alert(err.message || 'Could not record advance');
    } finally {
      setAdvanceLoading(false);
    }
  };

  const handleRefundAdvance = async (e) => {
    e.preventDefault();
    if (!advanceModalCustomer) return;
    const amt = parseFloat(String(refundAmount).replace(/[^\d.]/g, ''));
    if (!amt || amt <= 0) {
      alert('Enter a positive refund amount');
      return;
    }
    const mode = (refundPaymentMode || '').trim();
    if (!mode) {
      alert('Select how the refund was paid (cash, UPI, bank, etc.)');
      return;
    }
    const modeLabel =
      ADVANCE_PAYMENT_MODES.find((m) => m.value === mode)?.label || mode.replace(/_/g, ' ');
    const confirmed = window.confirm(
      `Refund ₹${amt.toLocaleString('en-IN')} to customer via ${modeLabel}? This will reduce today's ${mode === 'CASH' || mode === 'UPI' ? 'cash/UPI' : 'bank'} balance.`
    );
    if (!confirmed) return;
    try {
      setAdvanceLoading(true);
      await createCustomerAdvanceRefund({
        customerId: advanceModalCustomer.id,
        amount: amt,
        paymentMode: mode,
        description: refundDesc.trim() || undefined,
      });
      localStorage.setItem('lastAdvanceRefundPaymentMode', mode);
      setRefundAmount('');
      setRefundDesc('');
      await loadAdvanceData(advanceModalCustomer.id);
    } catch (err) {
      alert(err.message || 'Could not refund advance');
    } finally {
      setAdvanceLoading(false);
    }
  };

  const loadCustomers = async () => {
    try {
      setLoading(true);
      const customersData = await fetchCustomers();
      const finalCustomers = toList(customersData);
      setCustomers(finalCustomers);
      await loadRemainingAdvances(finalCustomers);
      localStorage.setItem('customers', JSON.stringify(finalCustomers));
    } catch (error) {
      console.error('Error loading customers:', error);
      // Fallback to localStorage if API fails
      try {
        const stored = localStorage.getItem('customers');
        if (stored) {
          const parsed = toList(JSON.parse(stored));
          setCustomers(parsed);
          await loadRemainingAdvances(parsed);
        } else {
          setCustomers([]);
          setRemainingAdvanceByCustomerId({});
        }
      } catch (localError) {
        console.error('Error loading from localStorage:', localError);
        setCustomers([]);
        setRemainingAdvanceByCustomerId({});
      }
    } finally {
      setLoading(false);
    }
  };

  const loadRemainingAdvances = async (customerList) => {
    const list = Array.isArray(customerList) ? customerList : [];
    if (list.length === 0) {
      setRemainingAdvanceByCustomerId({});
      return;
    }
    const results = await Promise.allSettled(
      list.map(async (customer) => {
        const summaryRaw = await fetchCustomerAdvanceSummary(customer.id);
        const summary = unwrapEntity(summaryRaw);
        return [customer.id, Number(summary?.remaining) || 0];
      })
    );
    const map = {};
    results.forEach((result) => {
      if (result.status === 'fulfilled' && Array.isArray(result.value)) {
        const [customerId, remaining] = result.value;
        map[customerId] = remaining;
      }
    });
    setRemainingAdvanceByCustomerId(map);
  };

  const onSubmit = async (data) => {
    try {
      setLoading(true);
      
      // Map form data to API format
      const apiData = {
        customerName: data.name,
        phone: data.phone,
        email: data.email || '',
        address: data.address || '',
        gstin: data.gstin || '',
        location: data.location || data.city || 'Bhondsi', // Use location field or fallback to city
        notes: data.notes || ''
      };

      if (editingCustomer) {
        // Update existing customer
        const updatedCustomer = toEntity(await updateCustomer(editingCustomer.id, apiData));
        setCustomers((prev) => {
          const list = toList(prev);
          return list.map((c) => (c.id === editingCustomer.id ? updatedCustomer : c));
        });
      } else {
        // Create new customer
        const newCustomer = toEntity(await createCustomer(apiData));
        setCustomers((prev) => [...toList(prev), newCustomer]);

        const tokenRaw =
          data.tokenAmount != null && data.tokenAmount !== undefined ? String(data.tokenAmount).trim() : '';
        const tokenAmt =
          tokenRaw === '' ? 0 : parseFloat(tokenRaw.replace(/[^\d.]/g, ''));
        if (tokenAmt > 0 && newCustomer?.id) {
          try {
            await createCustomerAdvance({
              customerId: newCustomer.id,
              amount: tokenAmt,
              paymentMode: data.tokenPaymentMode || 'CASH',
              description: 'Initial token at customer registration',
            });
          } catch (advErr) {
            console.error(advErr);
            alert(
              `Customer was saved, but the token could not be recorded: ${advErr.message || 'Unknown error'}. Add it using the token (💰) action on the customer row.`
            );
          }
        }
      }
      
      resetForm();
    } catch (error) {
      console.error('Error saving customer:', error);
      alert(`Error saving customer: ${error.message || 'Please try again'}`);
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (customer) => {
    setEditingCustomer(customer);
    // Map API data to form format
    const editData = {
      name: customer.customerName || customer.name || '',
      phone: customer.phone || '',
      email: customer.email || '',
      address: customer.address || '',
      city: customer.location || customer.city || '',
      state: customer.state || '',
      pincode: customer.pincode || '',
      gstin: customer.gstin || '',
      location: customer.location || customer.city || '',
      notes: customer.notes || ''
    };
    setFormData(editData);
    setValue('tokenAmount', '');
    // Update react-hook-form values
    Object.keys(editData).forEach(key => {
      setValue(key, editData[key]);
    });
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this customer?')) {
      try {
        setLoading(true);
        await deleteCustomer(id);
        setCustomers((prev) => toList(prev).filter((c) => c.id !== id));
      } catch (error) {
        console.error('Error deleting customer:', error);
        alert(`Error deleting customer: ${error.message || 'Please try again'}`);
      } finally {
        setLoading(false);
      }
    }
  };

  const openAddCustomer = () => {
    setEditingCustomer(null);
    setFormData({ ...CUSTOMER_FORM_DEFAULTS });
    reset(CUSTOMER_FORM_DEFAULTS);
    setShowForm(true);
  };

  const resetForm = () => {
    setFormData({ ...CUSTOMER_FORM_DEFAULTS });
    reset(CUSTOMER_FORM_DEFAULTS);
    setEditingCustomer(null);
    setShowForm(false);
  };

  const normalizeSearchText = (value) =>
    String(value ?? '')
      .toLowerCase()
      .replace(/\s+/g, ' ')
      .trim();

  const filteredCustomers = useMemo(() => {
    const list = Array.isArray(customers) ? customers : [];
    const query = normalizeSearchText(debouncedSearchQuery);
    if (!query) return list;
    return list.filter((customer) => {
      const customerName = customer.customerName || customer.name || '';
      const directMatch =
        normalizeSearchText(customerName).includes(query) ||
        normalizeSearchText(customer.phone).includes(query) ||
        normalizeSearchText(customer.email).includes(query) ||
        normalizeSearchText(customer.location).includes(query) ||
        normalizeSearchText(customer.city).includes(query) ||
        normalizeSearchText(customer.gstin).includes(query) ||
        normalizeSearchText(customer.notes).includes(query);
      if (directMatch) return true;
      // Fallback: include all plain values in one searchable blob for unexpected field names.
      const fallbackBlob = normalizeSearchText(Object.values(customer || {}).join(' '));
      return fallbackBlob.includes(query);
    });
  }, [customers, debouncedSearchQuery]);

  const totalPages = Math.ceil(filteredCustomers.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedCustomers = filteredCustomers.slice(startIndex, startIndex + itemsPerPage);

  const money = (n) =>
    Number(n || 0).toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  return (
    <div className="page-container page-container--full customers-page">
      <header className="page-header customers-header">
        <div>
          <h1 className="page-title">Customer Management</h1>
          <p className="page-subtitle">Manage profiles, contact details, and advance wallet</p>
        </div>
        <button type="button" className="primary-button" onClick={openAddCustomer}>
          + Add Customer
        </button>
      </header>

      {advanceModalCustomer && (
        <div className="modal-overlay" onClick={closeAdvanceModal}>
          <div className="modal-content advance-token-modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Token / Advance — {advanceModalCustomer.customerName || advanceModalCustomer.name || 'Customer'}</h3>
              <button type="button" className="modal-close" onClick={closeAdvanceModal}>
                ×
              </button>
            </div>
            <div className="modal-body">
              {advanceLoading && !advanceSummary ? (
                <p>Loading…</p>
              ) : (
                <>
                  <div className="summary-card-grid">
                    <div className="summary-card">
                      <span className="summary-card__label">Total advance</span>
                      <span className="summary-card__value">₹ {money(advanceSummary?.totalAdvance)}</span>
                    </div>
                    <div className="summary-card">
                      <span className="summary-card__label">Used on bills</span>
                      <span className="summary-card__value">₹ {money(advanceSummary?.totalUsed)}</span>
                    </div>
                    <div className="summary-card">
                      <span className="summary-card__label">Remaining</span>
                      <span className="summary-card__value">₹ {money(advanceSummary?.remaining)}</span>
                    </div>
                    <div className="summary-card">
                      <span className="summary-card__label">Old Bill Pending</span>
                      <span className="summary-card__value">₹ {money(advanceSummary?.oldBillPendingAmount)}</span>
                    </div>
                  </div>

                  <div className="advance-actions-grid">
                    <form onSubmit={handleAddAdvance} className="advance-add-form advance-action-card">
                      <h4 className="advance-section-title">Add advance / token</h4>
                      <div className="form-row">
                        <div className="form-group">
                          <label>Amount (₹) *</label>
                          <input
                            type="text"
                            inputMode="decimal"
                            value={advanceAmount}
                            onChange={(e) => setAdvanceAmount(e.target.value)}
                            placeholder="e.g. 5000"
                          />
                        </div>
                        <div className="form-group">
                          <label>Paid Via *</label>
                          <select
                            value={advancePaymentMode}
                            onChange={(e) => setAdvancePaymentMode(e.target.value)}
                            className="form-select"
                          >
                            {ADVANCE_PAYMENT_MODES.map((m) => (
                              <option key={m.value} value={m.value}>
                                {m.label}
                              </option>
                            ))}
                          </select>
                        </div>
                        <div className="form-group">
                          <label>Description</label>
                          <input
                            type="text"
                            value={advanceDesc}
                            onChange={(e) => setAdvanceDesc(e.target.value)}
                            placeholder="Optional note"
                          />
                        </div>
                      </div>
                      <button type="submit" className="primary-button" disabled={advanceLoading}>
                        Record advance
                      </button>
                    </form>

                    <form onSubmit={handleRefundAdvance} className="advance-add-form advance-action-card">
                      <h4 className="advance-section-title">Refund advance</h4>
                      <p className="advance-refund-hint">
                        Choose how you paid the customer back. Cash/UPI refunds reduce today&apos;s in-hand balance;
                        bank/cheque refunds reduce the bank side in reports.
                      </p>
                      <div className="form-row">
                        <div className="form-group">
                          <label>Refund Amount (₹) *</label>
                          <input
                            type="text"
                            inputMode="decimal"
                            value={refundAmount}
                            onChange={(e) => setRefundAmount(e.target.value)}
                            placeholder="e.g. 1000"
                          />
                        </div>
                        <div className="form-group">
                          <label>Refund via *</label>
                          <select
                            value={refundPaymentMode}
                            onChange={(e) => setRefundPaymentMode(e.target.value)}
                            className="form-select"
                          >
                            {ADVANCE_PAYMENT_MODES.map((m) => (
                              <option key={m.value} value={m.value}>
                                {m.label}
                              </option>
                            ))}
                          </select>
                        </div>
                        <div className="form-group">
                          <label>Note</label>
                          <input
                            type="text"
                            value={refundDesc}
                            onChange={(e) => setRefundDesc(e.target.value)}
                            placeholder="Optional note"
                          />
                        </div>
                      </div>
                      <button type="submit" className="secondary-button" disabled={advanceLoading}>
                        Refund
                      </button>
                    </form>
                  </div>

                  <h4 className="advance-section-title">History</h4>
                  <div className="advance-history-wrap">
                    <table className="data-table advance-history-table">
                      <thead>
                        <tr>
                          <th>Type</th>
                          <th>Date</th>
                          <th>Amount (₹)</th>
                          <th>Details</th>
                        </tr>
                      </thead>
                      <tbody>
                        {advanceHistory.length === 0 ? (
                          <tr>
                            <td colSpan={4} style={{ textAlign: 'center' }}>
                              No advance activity yet
                            </td>
                          </tr>
                        ) : (
                          advanceHistory.map((row, i) => (
                            <tr key={`${row.type}-${row.createdAt}-${i}`}>
                              <td>
                                {row.type === 'DEPOSIT'
                                  ? 'Deposit'
                                  : row.type === 'USAGE'
                                    ? 'Applied to bill'
                                    : row.type === 'REFUND'
                                      ? 'Refund'
                                      : row.type === 'REVERSAL_CREDIT'
                                        ? 'Bill reversal'
                                        : row.type || 'Entry'}
                              </td>
                              <td>{row.createdAt ? new Date(row.createdAt).toLocaleString() : '—'}</td>
                              <td>{money(row.amount)}</td>
                              <td>
                                {row.type === 'USAGE' && row.billId
                                  ? `${row.billKind || ''} bill #${row.billId}`
                                  : [
                                      row.description || '—',
                                      row.paymentMode
                                        ? `(via ${String(row.paymentMode).replace(/_/g, ' ')})`
                                        : null,
                                    ]
                                      .filter(Boolean)
                                      .join(' ')}
                              </td>
                            </tr>
                          ))
                        )}
                      </tbody>
                    </table>
                  </div>
                </>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Customer Form Modal */}
      {showForm && (
        <div className="modal-overlay" onClick={resetForm}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>{editingCustomer ? 'Edit Customer' : 'Add New Customer'}</h3>
              <button className="modal-close" onClick={resetForm}>×</button>
            </div>
            <div className="modal-body">
              <form onSubmit={handleSubmit(onSubmit)}>
                <div className="form-group">
                  <label>Customer Name *</label>
                  <input
                    type="text"
                    {...register('name')}
                    placeholder="Enter customer name"
                  />
                  {errors.name && (
                    <span className="error-message">{errors.name.message}</span>
                  )}
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label>Phone Number *</label>
                    <input
                      type="tel"
                      {...register('phone', {
                        onChange: (e) => {
                          const digits = String(e.target.value || '').replace(/\D/g, '').slice(0, 10);
                          e.target.value = digits;
                          setValue('phone', digits, { shouldValidate: true, shouldDirty: true });
                        }
                      })}
                      placeholder="Enter phone number (10 digits)"
                      inputMode="numeric"
                      maxLength={10}
                      pattern="[0-9]{10}"
                      autoComplete="off"
                    />
                    {errors.phone && (
                      <span className="error-message">{errors.phone.message}</span>
                    )}
                  </div>
                  <div className="form-group">
                    <label>Email</label>
                    <input
                      type="email"
                      {...register('email')}
                      placeholder="Enter email address"
                    />
                    {errors.email && (
                      <span className="error-message">{errors.email.message}</span>
                    )}
                  </div>
                </div>
                <div className="form-group">
                  <label>Address</label>
                  <textarea
                    {...register('address')}
                    placeholder="Enter address"
                    rows="2"
                  />
                  {errors.address && (
                    <span className="error-message">{errors.address.message}</span>
                  )}
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label>City</label>
                    <input
                      type="text"
                      {...register('city')}
                      placeholder="Enter city"
                    />
                    {errors.city && (
                      <span className="error-message">{errors.city.message}</span>
                    )}
                  </div>
                  <div className="form-group">
                    <label>State</label>
                    <input
                      type="text"
                      {...register('state')}
                      placeholder="Enter state"
                    />
                    {errors.state && (
                      <span className="error-message">{errors.state.message}</span>
                    )}
                  </div>
                  <div className="form-group">
                    <label>Pincode</label>
                    <input
                      type="text"
                      {...register('pincode')}
                      placeholder="Enter pincode (6 digits)"
                    />
                    {errors.pincode && (
                      <span className="error-message">{errors.pincode.message}</span>
                    )}
                  </div>
                </div>
                <div className="form-row">
                  <div className="form-group">
                    <label>Location *</label>
                    <select
                      {...register('location')}
                      className="form-select"
                    >
                      <option value="Bhondsi">Bhondsi</option>
                      <option value="Tapugada">Tapugada</option>
                    </select>
                    {errors.location && (
                      <span className="error-message">{errors.location.message}</span>
                    )}
                  </div>
                  <div className="form-group">
                    <label>GSTIN</label>
                    <input
                      type="text"
                      {...register('gstin')}
                      placeholder="Enter GSTIN (optional)"
                    />
                    {errors.gstin && (
                      <span className="error-message">{errors.gstin.message}</span>
                    )}
                  </div>
                </div>
                <div className="form-group">
                  <label>Notes</label>
                  <textarea
                    {...register('notes')}
                    placeholder="Additional notes (optional)"
                    rows="2"
                  />
                  {errors.notes && (
                    <span className="error-message">{errors.notes.message}</span>
                  )}
                </div>
                {!editingCustomer && (
                  <div className="form-row">
                    <div className="form-group">
                      <label>Token amount</label>
                      <input
                        type="text"
                        inputMode="decimal"
                        {...register('tokenAmount')}
                        placeholder="Enter token amount (optional)"
                        autoComplete="off"
                      />
                      {errors.tokenAmount && (
                        <span className="error-message">{errors.tokenAmount.message}</span>
                      )}
                    </div>
                    <div className="form-group">
                      <label>Token Paid Via</label>
                      <select {...register('tokenPaymentMode')} className="form-select">
                        <option value="CASH">Cash</option>
                        <option value="UPI">UPI</option>
                        <option value="BANK_TRANSFER">Bank transfer</option>
                        <option value="CHEQUE">Cheque</option>
                      </select>
                    </div>
                    <span className="customers-field-hint">
                      If token amount is set, advance is recorded with selected payment mode (applied to future bills).
                    </span>
                  </div>
                )}
                <div className="form-actions">
                  <button type="submit" className="primary-button">
                    {editingCustomer ? 'Update Customer' : 'Add Customer'}
                  </button>
                  <button type="button" className="secondary-button" onClick={resetForm}>
                    Cancel
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Search */}
      <div className="page-toolbar">
        <div className="page-toolbar__grow search-bar search-wrapper">
          <span className="search-icon">🔍</span>
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value);
              setCurrentPage(1);
            }}
            placeholder="Search customers by name, phone, email..."
            className="search-bar__input search-input"
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => {
                setSearchQuery('');
                setCurrentPage(1);
              }}
              className="search-bar__clear search-clear-btn"
            >
              ×
            </button>
          )}
        </div>
      </div>

      {/* Customers Table */}
      <div className="section-card customers-table-container">
        {loading ? (
          <Loading message="Loading customers..." />
        ) : filteredCustomers.length > 0 ? (
          <>
            <div className="table-scroll sales-table-wrapper">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>Name</th>
                    <th>Phone</th>
                    <th>Remaining Advance</th>
                    <th>Notes</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {paginatedCustomers.map((customer) => (
                    <tr key={customer.id}>
                      <td className="date-cell">{customer.customerName || customer.name || '-'}</td>
                      <td>{customer.phone || '-'}</td>
                      <td>₹ {money(remainingAdvanceByCustomerId[customer.id])}</td>
                      <td>{customer.notes || '-'}</td>
                      <td>
                        <div className="action-buttons">
                          <button
                            type="button"
                            className="action-btn action-btn-advance"
                            onClick={() => openAdvanceModal(customer)}
                            title="Token / advance"
                          >
                            💰
                          </button>
                          <button
                            className="action-btn"
                            onClick={() => handleEdit(customer)}
                            title="Edit"
                          >
                            ✏️
                          </button>
                          <button
                            className="action-btn"
                            onClick={() => handleDelete(customer.id)}
                            title="Delete"
                          >
                            🗑️
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {totalPages > 1 && (
              <div className="pagination-bar pagination">
                <button
                  type="button"
                  className="secondary-button secondary-button--sm pagination-btn"
                  onClick={() => setCurrentPage(prev => Math.max(1, prev - 1))}
                  disabled={currentPage === 1}
                >
                  Previous
                </button>
                <span className="pagination-bar__info pagination-info">
                  Page {currentPage} of {totalPages}
                </span>
                <button
                  type="button"
                  className="secondary-button secondary-button--sm pagination-btn"
                  onClick={() => setCurrentPage(prev => Math.min(totalPages, prev + 1))}
                  disabled={currentPage === totalPages}
                >
                  Next
                </button>
              </div>
            )}
          </>
        ) : (
          <div className="empty-state-wrapper">
            <span className="empty-icon">👥</span>
            <p className="empty-state">No customers found</p>
            <p className="empty-subtitle">
              {searchQuery ? 'Try a different search term' : 'Click "Add Customer" to add your first customer'}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default Customers;

